import{_ as d,C as r,o as s,c as i,j as t,a,E as n,ag as l}from"./chunks/framework.HG0H2VLS.js";const v=JSON.parse('{"title":"LiveDashboard","description":"","frontmatter":{},"headers":[],"relativePath":"cc-templates/live-dashboard.md","filePath":"cc-templates/live-dashboard.md"}'),c={name:"cc-templates/live-dashboard.md"};function h(u,e,b,g,p,m){const o=r("ComponentDemo");return s(),i("div",null,[e[0]||(e[0]=t("hr",null,null,-1)),e[1]||(e[1]=t("h2",{id:"title-livedashboard",tabindex:"-1"},[a("title: LiveDashboard "),t("a",{class:"header-anchor",href:"#title-livedashboard","aria-label":'Permalink to "title: LiveDashboard"'},"​")],-1)),e[2]||(e[2]=t("h1",{id:"livedashboard",tabindex:"-1"},[a("LiveDashboard "),t("a",{class:"header-anchor",href:"#livedashboard","aria-label":'Permalink to "LiveDashboard"'},"​")],-1)),e[3]||(e[3]=t("blockquote",null,[t("p",null,[t("code",null,"/control/live-dashboard"),a(" on v3 on the Flowbite application-UI benchmark: StatCard Xl KPI tiles (Online now, Page views today, Busiest channel), Chart hero (today blue vs average orange dashed — the only accent pair passing the dataviz validator in both themes; Now marker, crosshair, direct labels, table view), online members list, three leaderboards with share bars, Top articles table, live 30s refresh with Live badge / Updated / Pause")])],-1)),n(o,{src:"/demos/src/cc/templates/LiveDashboard/LiveDashboard.html"}),e[4]||(e[4]=l('<h2 id="classic-→-v3" tabindex="-1">Classic → v3 <a class="header-anchor" href="#classic-→-v3" aria-label="Permalink to &quot;Classic → v3&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic</th><th>v3</th></tr></thead><tbody><tr><td>Online Users: Members n / Guests n, list of online members (avatar, name, company), view more (10 +10)</td><td>KPI <strong>Online now</strong> (members + guests, breakdown Members / Guests) + <strong>Online members</strong> card: avatar, name, company; Show more +10; a member-count badge</td></tr><tr><td>Page Views: Chart.js line, &quot;Today&quot; vs &quot;Average&quot;, 24-hour timeline</td><td><strong>Page views</strong> hero card (Chart pattern): today vs average by hour, delta Badge &quot;+n% vs average&quot; (today so far against the average to this hour), &quot;Now&quot; marker, crosshair tooltip, direct labels, legend, <strong>View as table</strong></td></tr><tr><td>&quot;The data below is sampled across last N hours&quot;</td><td>A meta line: clock icon, &quot;Rankings below are sampled across the last <strong>N hours</strong> — as far back as it takes to reach 2,000 views, up to 24 hours&quot; (getTimeFrame&#39;s own rule, now said aloud)</td></tr><tr><td>Top Author / Top Channel / Top Topic lists (views + name), view more (4 +8 / 5 +10 / 5 +10)</td><td>Three leaderboard cards: rank, name (avatar for authors), views right-aligned, <strong>share-of-top bar</strong>; Show more with classic&#39;s steps</td></tr><tr><td>Top Article table (Title, Author, Published, Views), view more (5 +10)</td><td><strong>Top articles</strong> Datatables + Table: title link, author with avatar, published date, views right-aligned; Show more +10</td></tr><tr><td><code>setTimeout(aosGetData(&#39;all&#39;), 30000)</code> — silent</td><td>Same 30s refresh, now visible: <strong>Live</strong> Badge with a pulsing dot, &quot;Updated n s ago&quot;, <strong>Pause / Resume</strong></td></tr><tr><td>—</td><td>KPI <strong>Page views today</strong> (since midnight; breakdown vs average, this hour) and <strong>Busiest channel</strong> (views, share) — derived from data classic already loads</td></tr></tbody></table><p>Links are classic&#39;s own, in a new tab as classic opens them: contacts (UserCode), channel (ChannelCode), taxonomy-manager-screen (TaxonomyCategoryCode), standard-item-edit view (StandardItemCode).</p><h2 id="the-flowbite-moves" tabindex="-1">The Flowbite moves <a class="header-anchor" href="#the-flowbite-moves" aria-label="Permalink to &quot;The Flowbite moves&quot;">​</a></h2><p>KPI tiles across the top (StatCard Xl, related figures folded into one tile&#39;s breakdown); one hero chart with its headline in the card header; a &quot;latest customers&quot;-style people list; &quot;top products&quot;-style ranked lists with share bars; a compact table card; a small live status in the header. Right-aligned numbers with tabular figures <strong>on this dashboard</strong> (Mark, 2026-10-05; the listing demos stay left-aligned).</p><h2 id="chart-colour-—-validated-not-chosen" tabindex="-1">Chart colour — validated, not chosen <a class="header-anchor" href="#chart-colour-—-validated-not-chosen" aria-label="Permalink to &quot;Chart colour — validated, not chosen&quot;">​</a></h2><p><code>scripts/validate_palette.js</code> (dataviz skill), both themes:</p><table tabindex="0"><thead><tr><th>Pair</th><th>Result</th></tr></thead><tbody><tr><td>blue + slate (<code>text-contrast</code>) dashed</td><td><strong>FAIL</strong>: normal-vision ΔE 13.9 (&lt; 15) and the slate reads as grey</td></tr><tr><td>blue + purple (the designer&#39;s two-series pair on Contract Analysis)</td><td><strong>FAIL</strong>: deutan ΔE <strong>2.5</strong>, near-identical to a deuteranope</td></tr><tr><td>blue (<code>accent-blue-solid</code>) + orange (<code>accent-orange-solid</code>)</td><td>PASS every check, light and dark: protan ΔE 27.6, tritan 34.4 (used 2026-10-05 → 10-07)</td></tr><tr><td><strong>lagoon (<code>accent-lagoon-solid</code>, Lagoon/9) + purple (<code>accent-purple-solid</code>, Purple/600)</strong></td><td><strong>PASS</strong> CVD in both themes: deutan ΔE 16.0, tritan 19.8, normal 28.6. Purple is 2.72:1 on the dark card (WARN) — relieved by the direct labels, the legend and the table view</td></tr></tbody></table><p><strong>Current (designer, 2026-10-07): Today = lagoon, solid, gradient fill; Average = purple, dashed, no fill</strong> — the same pair as Contract Analysis. Both are direct-labelled and in a line-style legend, so identity never rests on hue alone. Text stays in text tokens.</p><p>KPI tiles follow the house card rule — lead with lagoon, blue only after the other accents are used: Online now <code>lagoon</code>, Page views today <code>jade</code> (was blue), Busiest channel <code>violet-radix</code>.</p><p>Leaderboard share bars fill with <code>accent-lagoon-solid</code> (was <code>surface-brand</code>), matching the Today line in both themes (<code>surface-brand-light</code> is the same hex in light but lightens in dark).</p><h2 id="layout-values-all-borrowed-no-new-tokens" tabindex="-1">Layout values (all borrowed, no new tokens) <a class="header-anchor" href="#layout-values-all-borrowed-no-new-tokens" aria-label="Permalink to &quot;Layout values (all borrowed, no new tokens)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Token</th><th>From</th></tr></thead><tbody><tr><td>Page grid</td><td><strong>one</strong> 3-column grid; KPI row, hero row and leaderboards are subgrids of it (chart spans 2, online list 1)</td><td>— so every column edge lines up top to bottom. Measured 2026-10-05: before, the 2fr / 1fr hero row sat 6px off the columns above and below; after, all rows share 320–703 / 719–1103 / 1119–1502 at 1600</td></tr><tr><td>Block gap</td><td><code>spacing-5</code> (12px / <code>spacing-4</code> in full width); the subgrids take <code>gap: inherit</code></td><td>UpdateScreen / record screens&#39; card gap. A subgrid inherits only the COLUMN gap, so stacked KPI tiles first touched (Mark, 2026-10-05); measured after: 16px stacked and side by side, 12px in full width</td></tr><tr><td>People-grid track minimum</td><td><code>size-5</code> (280px)</td><td>—</td></tr><tr><td>Card chrome</td><td><code>spacing-6</code> padding, <code>spacing-5</code> gap, <code>surface-primary</code>, <code>radius-md</code></td><td>the Chart pattern&#39;s own card</td></tr><tr><td>Top-level card border / shadow</td><td><code>border/card</code>, <code>shadow/2xs</code> (standard width)</td><td>the CC top-level card rule</td></tr><tr><td>Card title</td><td>title, semibold, <code>fixed-md</code></td><td>RecordSection&#39;s title</td></tr><tr><td>Share bar</td><td><code>spacing-2</code> tall, <code>radius-full</code>, <code>surface-contrast</code> track, <code>surface-brand</code> fill</td><td>RoomCard&#39;s Figma-built progress bar</td></tr><tr><td>Canvas</td><td>min <code>size-6</code> (320px), grows with the card; min <code>size-5</code> on a narrow page</td><td>—</td></tr><tr><td>Live dot</td><td><code>spacing-3</code></td><td>the Badge&#39;s icon scale</td></tr><tr><td>People-row padding</td><td><code>spacing-3</code> / <code>spacing-4</code></td><td>DropdownItem&#39;s row padding</td></tr></tbody></table><h2 id="responsive" tabindex="-1">Responsive <a class="header-anchor" href="#responsive" aria-label="Permalink to &quot;Responsive&quot;">​</a></h2><ul><li><strong>KPI tiles:</strong> each wraps in a size container (<code>cc-live-kpi</code>; its width is the grid track&#39;s, which follows the space available). Below 384px the breakdown moves under the value, using StatCard&#39;s own stacked arrangement.</li><li><strong>Hero row:</strong> below 1023 (<code>cs-page</code>) the chart and the online list each take the full row; the KPI tiles and leaderboards keep three columns. Below 767 the whole grid is one column. The people list is an intrinsic grid (one column in the side card, two or three when it spans the page).</li><li><strong>Below 767 (<code>cs-page</code>):</strong> the hour axis labels every 6 hours on a narrow chart, Top articles drops Published, and titles / authors wrap (the base Table&#39;s <code>nowrap</code> made the table 779px in a 294px card). The header&#39;s &quot;Updated&quot; text goes below 767 on <code>cs-main</code> (the header is outside the page column).</li><li>Measured at 390: 390/390, nothing past the edge.</li></ul><h2 id="full-width" tabindex="-1">Full width <a class="header-anchor" href="#full-width" aria-label="Permalink to &quot;Full width&quot;">​</a></h2><p>Contract Analysis&#39;s dashboard treatment (the precedent for a dashboard): the shell takes the page padding away, so the page keeps a 12px inset (<code>spacing-4</code>) and the gaps tighten to 12px; cards keep their own edges and radius and drop the card shadow (full width is flat). The first pass removed the gaps but kept radius and borders, which doubled every seam into 2px; the subgrid keeps the columns aligned here too (308–699 / 711–1102 / 1114–1505 at 1600).</p><h2 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h2><p>The canvas is <code>role=&quot;img&quot;</code> with a label; <strong>View as table</strong> gives every hour&#39;s numbers. The ticking &quot;Updated&quot; text is not a live region; only Pause / Resume are announced. Pause is <code>aria-pressed</code>. No pulse, value highlight or bar transition under reduced motion. Row links have a background-only hover (the menu-link rule).</p><h2 id="gotchas-hit-kept-so-they-are-not-hit-again" tabindex="-1">Gotchas hit (kept so they are not hit again) <a class="header-anchor" href="#gotchas-hit-kept-so-they-are-not-hit-again" aria-label="Permalink to &quot;Gotchas hit (kept so they are not hit again)&quot;">​</a></h2><ul><li>A leftover, unopened comment line swallowed the next rule (the delta colour). The braces balanced, so a brace count can&#39;t catch this; listing the rules that match the element did.</li><li>StatCard&#39;s <code>.stat-card__breakdown-value</code> colour outranks a single-class override; the delta colour is qualified with it.</li><li>The visually-hidden &quot;views&quot; labels are absolutely positioned; with no positioned ancestor they escaped the page scroller&#39;s clip and made the document 1,285px tall in a 900px window (a second, window-level scroll). <code>.cc-live__card</code> is now <code>position: relative</code>; the document equals the window in all layouts.</li></ul><h2 id="backend-todo-backend-livedashboard" tabindex="-1">Backend (<code>TODO(backend:LiveDashboard)</code>) <a class="header-anchor" href="#backend-todo-backend-livedashboard" aria-label="Permalink to &quot;Backend (`TODO(backend:LiveDashboard)`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>id</th><th>What</th></tr></thead><tbody><tr><td><code>live-data</code></td><td>Every count is mock. Live = Dashboard.cfc: getOnlineUsers, getDayPageViews (today + average by hour), getTimeFrame, getCreatorViews, getChannelViews, getTaxonomyCategoryViews, getArticleViews, with MaxRows paging (classic&#39;s initial counts + steps are in <code>live-dashboard-data.js</code> → <code>paging</code>)</td></tr><tr><td><code>live-refresh</code></td><td>Poll the same data every 30s (classic&#39;s dashboard.js) and re-render; honour Pause. Classic redirects on &quot;Access Denied&quot; (security code 14), so keep that</td></tr></tbody></table><h2 id="top-articles-—-column-fit-2026-10-07" tabindex="-1">Top articles — column fit (2026-10-07) <a class="header-anchor" href="#top-articles-—-column-fit-2026-10-07" aria-label="Permalink to &quot;Top articles — column fit (2026-10-07)&quot;">​</a></h2><p><code>table[data-fit]</code> + <strong>DatatablesFit.js</strong> (<code>src/components/Datatables/</code>), the listings&#39; fit: Article and Views always show; Published drops first, then Author, into the kebab&#39;s detail row; spare width is shared (Author <code>data-snug</code>, capped at 224px, so the long titles take the rest). Replaces the ≤767 rule that hid Published outright, and the title cell&#39;s <code>inline-size: 100%</code>.</p>',25))])}const k=d(c,[["render",h]]);export{v as __pageData,k as default};
